// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// The user experience could use more... flair.
const mockCartWithItems = {
  items: [
    { id: '1', name: 'Army Surplus Dress', price: 49.99 },
    { id: '2', name: 'Toledo Earrings', price: 25.00 }
  ],
  total: 74.99,
  clearCart: vi.fn()
};

const mockPayment = {
  processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-4077' })
};

const renderCheckout = (cartOverrides = {}, paymentOverrides = {}) => {
  const cart = { ...mockCartWithItems, ...cartOverrides };
  const payment = { ...mockPayment, ...paymentOverrides };

  return render(
    <CartProvider value={cart}>
      <PaymentProvider value={payment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    renderCheckout();

    // Shipping step - I know what people need. I'm from Toledo.
    await user.type(screen.getByLabelText(/street address/i), '4077 MASH Lane');
    await user.type(screen.getByLabelText(/city/i), 'Toledo');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Maxwell Q Klinger');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/army surplus dress/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-4077');
    });
  });
});

describe('Checkout - Form Validation', () => {
  it('displays shipping errors for empty required fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error States', () => {
  it('displays payment failure and allows retry', async () => {
    const user = userEvent.setup();
    const failingPayment = {
      processPayment: vi.fn().mockRejectedValueOnce(new Error('Card declined'))
    };
    renderCheckout({}, failingPayment);

    // Navigate to review step (abbreviated)
    // ... fill forms ...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent('Card declined');
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout({ items: [], total: 0 });

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });
});

describe('Checkout - Accessibility', () => {
  it('has accessible progress navigation', () => {
    renderCheckout();

    const nav = screen.getByRole('navigation', { name: /checkout progress/i });
    expect(nav).toBeInTheDocument();
    expect(screen.getByText('Shipping').closest('li')).toHaveAttribute('aria-current', 'step');
  });

  it('announces loading state to screen readers', async () => {
    const user = userEvent.setup();
    renderCheckout();
    // Navigate to review...

    const submitButton = screen.getByRole('button', { name: /place order/i });
    await user.click(submitButton);

    expect(submitButton).toHaveAttribute('aria-busy', 'true');
  });
});
